/**
 * UiPatternStore — loads, indexes, and queries the cached UIVerse UI pattern library.
 *
 * The pattern library is generated by backend/scripts/scrape-uiverse-patterns.ts
 * from the uiverse-io/galaxy repo (3,800+ community-made UI components).
 *
 * Provides the gui_builder tool with real, working HTML/CSS code examples for
 * buttons, cards, inputs, toggles, and other UI widgets that it can reference
 * when designing app interfaces.
 */
import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
const __dirname = path.dirname(fileURLToPath(import.meta.url));
const PROJECT_ROOT = path.resolve(__dirname, '..', '..', '..', '..');
const PATTERNS_FILE = path.join(PROJECT_ROOT, 'data', 'ui-patterns', 'patterns.json');
// ─── Store ──────────────────────────────────────────────────────────────────
export class UiPatternStore {
    collection = null;
    loaded = false;
    /** Index: type → array of patterns */
    indexByType = new Map();
    /** Index: tag → array of pattern IDs */
    indexByTag = new Map();
    /** Index: style tag → array of pattern types */
    styleIndex = new Map();
    // ─── Loading ────────────────────────────────────────────────────────────
    load() {
        if (this.loaded)
            return;
        if (!fs.existsSync(PATTERNS_FILE)) {
            console.warn(`[UiPatternStore] Patterns file not found: ${PATTERNS_FILE}`);
            console.warn('[UiPatternStore] Run: npx tsx backend/scripts/scrape-uiverse-patterns.ts');
            return;
        }
        try {
            const raw = fs.readFileSync(PATTERNS_FILE, 'utf-8');
            this.collection = JSON.parse(raw);
            this.buildIndex();
            this.loaded = true;
            console.log(`[UiPatternStore] Loaded ${this.collection.totalPatterns} patterns across ` +
                `${Object.keys(this.collection.patternsByType).length} types`);
        }
        catch (err) {
            console.error(`[UiPatternStore] Failed to load patterns: ${err}`);
        }
    }
    buildIndex() {
        if (!this.collection)
            return;
        // Index by type
        for (const [type, patterns] of Object.entries(this.collection.patternsByType)) {
            this.indexByType.set(type, patterns);
        }
        // Index by tag
        for (const pattern of this.collection.allPatterns) {
            for (const tag of pattern.tags) {
                if (!this.indexByTag.has(tag)) {
                    this.indexByTag.set(tag, []);
                }
                this.indexByTag.get(tag).push(pattern.id);
            }
            // Index style tags → types
            for (const styleTag of pattern.styleTags) {
                if (!this.styleIndex.has(styleTag)) {
                    this.styleIndex.set(styleTag, new Set());
                }
                this.styleIndex.get(styleTag).add(pattern.type);
            }
        }
    }
    // ─── Queries ───────────────────────────────────────────────────────────
    /** Get all patterns of a specific type */
    getByType(type, limit = 10) {
        if (!this.loaded)
            this.load();
        const patterns = this.indexByType.get(type);
        if (!patterns)
            return [];
        // Shuffle and take <limit>
        const shuffled = [...patterns];
        for (let i = shuffled.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
        }
        return shuffled.slice(0, limit);
    }
    /** Get patterns matching certain tags */
    getByTags(matchingTags, limit = 5) {
        if (!this.loaded)
            this.load();
        if (!this.collection)
            return [];
        const matched = new Set();
        for (const tag of matchingTags) {
            const ids = this.indexByTag.get(tag);
            if (ids)
                ids.forEach(id => matched.add(id));
        }
        const result = [];
        for (const pattern of this.collection.allPatterns) {
            if (matched.has(pattern.id)) {
                result.push(pattern);
                if (result.length >= limit)
                    break;
            }
        }
        return result;
    }
    /** Get pattern types relevant to a goal keyword */
    getRelevantTypesForGoal(goal) {
        const goalLower = goal.toLowerCase();
        const keywordTypeMap = {
            search: ['input', 'button'],
            filter: ['input', 'checkbox', 'toggle'],
            form: ['input', 'button', 'checkbox', 'radio', 'form'],
            login: ['input', 'button', 'form', 'card'],
            player: ['button', 'card', 'toggle'],
            settings: ['toggle', 'checkbox', 'input', 'radio', 'button'],
            chat: ['input', 'button', 'card', 'notification'],
            list: ['card', 'button', 'input'],
            media: ['card', 'button', 'loader', 'notification'],
            nav: ['button', 'card', 'tooltip'],
            notify: ['notification', 'tooltip', 'button'],
            loading: ['loader', 'card', 'notification'],
            game: ['button', 'card', 'toggle', 'loader'],
            auth: ['input', 'button', 'form', 'card'],
            profile: ['card', 'button', 'input'],
            dashboard: ['card', 'button', 'input', 'toggle', 'form'],
        };
        const types = new Set();
        types.add('button'); // Buttons are universally relevant
        types.add('card'); // Cards too
        for (const [keyword, relevantTypes] of Object.entries(keywordTypeMap)) {
            if (goalLower.includes(keyword)) {
                relevantTypes.forEach(t => types.add(t));
            }
        }
        return [...types];
    }
    /** Build formatted context for the LLM prompt */
    getContextForGoal(goal, deep = false) {
        if (!this.loaded)
            this.load();
        if (!this.collection) {
            return {
                totalPatterns: 0,
                patternsByType: {},
                samplePatterns: [],
                typeRecommendations: [],
            };
        }
        const relevantTypes = this.getRelevantTypesForGoal(goal);
        // Count by type
        const patternsByType = {};
        for (const [type, patterns] of Object.entries(this.collection.patternsByType)) {
            patternsByType[type] = patterns.length;
        }
        // Sample patterns relevant to the goal
        const maxSamples = deep ? 24 : 12;
        const samplesPerType = deep ? 4 : 2;
        const snippetLen = deep ? 600 : 400;
        const maxTags = deep ? 12 : 8;
        const samplePatterns = [];
        for (const type of relevantTypes) {
            const samples = this.getByType(type, samplesPerType);
            for (const s of samples) {
                samplePatterns.push({
                    type: s.type,
                    subType: s.subType,
                    tags: s.tags.slice(0, maxTags),
                    colors: s.colors,
                    styleTags: s.styleTags.slice(0, 6),
                    htmlSnippet: s.htmlSnippet.slice(0, snippetLen),
                });
                if (samplePatterns.length >= maxSamples)
                    break;
            }
            if (samplePatterns.length >= maxSamples)
                break;
        }
        // Use keyword recommendations
        const typeRecommendations = [
            { goalKeyword: 'form/login', recommendedTypes: ['input', 'button', 'checkbox'], description: 'Use text inputs for fields, styled buttons for submit, checkboxes for agreements' },
            { goalKeyword: 'media/player', recommendedTypes: ['button', 'toggle', 'card'], description: 'Use icon buttons for playback controls, toggle switches for repeat/shuffle, cards for track display' },
            { goalKeyword: 'search/browse', recommendedTypes: ['input', 'button', 'card'], description: 'Use search input in topbar, filter buttons/chips, cards for results grid' },
            { goalKeyword: 'settings', recommendedTypes: ['toggle', 'checkbox', 'radio', 'input', 'button'], description: 'Use toggles for binary options, radio for selections, inputs for custom values' },
            { goalKeyword: 'dashboard', recommendedTypes: ['card', 'button', 'input', 'toggle', 'loader'], description: 'Use stat cards for metrics, buttons for actions, toggles for filters, loaders for data states' },
        ];
        return {
            totalPatterns: this.collection.totalPatterns,
            patternsByType,
            samplePatterns,
            typeRecommendations,
        };
    }
    /** Format context as a readable text block for LLM prompt injection */
    formatContextForPrompt(context) {
        if (context.totalPatterns === 0)
            return '';
        const parts = ['🎨 UIVERSE — REAL HTML/CSS UI COMPONENT LIBRARY (3,800+ patterns)'];
        parts.push('━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━');
        parts.push(`Total components cached: ${context.totalPatterns.toLocaleString()}`);
        parts.push(`Available types: ${Object.entries(context.patternsByType).sort((a, b) => b[1] - a[1]).map(([t, c]) => `${t} (${c})`).join(', ')}`);
        parts.push('');
        // Add type recommendations
        parts.push('── Widget Type Recommendations ──');
        for (const rec of context.typeRecommendations) {
            parts.push(`  For ${rec.goalKeyword}:`);
            parts.push(`    Recommended: ${rec.recommendedTypes.join(', ')}`);
            parts.push(`    ${rec.description}`);
        }
        // Add sample patterns
        if (context.samplePatterns.length > 0) {
            parts.push('');
            parts.push('── Real Code Examples (relevant to this app) ──');
            for (const pat of context.samplePatterns.slice(0, 8)) {
                const colorStr = Object.values(pat.colors).filter(Boolean).slice(0, 3).join(', ');
                parts.push(`  Type: ${pat.type}${pat.subType ? ` (${pat.subType})` : ''}`);
                parts.push(`    Tags: ${pat.tags.join(', ')}`);
                if (colorStr)
                    parts.push(`    Colors: ${colorStr}`);
                if (pat.styleTags.length > 0)
                    parts.push(`    Style: ${pat.styleTags.join(', ')}`);
                if (pat.htmlSnippet) {
                    // Show just the outer HTML structure, not the full code
                    const snippetLines = pat.htmlSnippet.split('\n').slice(0, 6).join('\n').trim();
                    parts.push(`    Code preview:\n    \`\`\`\n${snippetLines}\n    \`\`\``);
                }
                parts.push('');
            }
        }
        return parts.join('\n');
    }
    /** Check if the pattern cache is available */
    isAvailable() {
        if (this.loaded && this.collection)
            return true;
        return fs.existsSync(PATTERNS_FILE);
    }
    /** Get the total count */
    getTotalCount() {
        if (!this.loaded)
            this.load();
        return this.collection?.totalPatterns || 0;
    }
}
// ─── Singleton ──────────────────────────────────────────────────────────────
let _instance = null;
export function getUiPatternStore() {
    if (!_instance) {
        _instance = new UiPatternStore();
        try {
            _instance.load();
        }
        catch (err) {
            console.warn('[UiPatternStore] Failed to load on init:', err);
        }
    }
    return _instance;
}
